export function getBattleProblem(slug: string): BattleProblem | undefined {
  return BATTLE_PROBLEMS.find((p) => p.slug === slug)
}

/** Picks numQuestions problems matching the given filters, in random order. */
export function pickBattleQuestions(config: { difficulty: string; topics: string[] }, numQuestions: number): string[] {
  let pool = BATTLE_PROBLEMS
  if (config.difficulty !== "Mixed") {
    pool = pool.filter((p) => p.difficulty === config.difficulty)
  }
  if (config.topics.length > 0) {
    pool = pool.filter((p) => config.topics.includes(p.topic))
  }
  if (pool.length === 0) pool = BATTLE_PROBLEMS // filters matched nothing — fall back to the full bank rather than error

  const shuffled = [...pool].sort(() => Math.random() - 0.5)
  const picked: string[] = []
  for (let i = 0; i < numQuestions; i++) {
    picked.push(shuffled[i % shuffled.length].slug) // wrap around if numQuestions > pool size
  }
  return picked
}
